Set-Location -LiteralPath $PSScriptRoot
$msg = 'email: stop sending a customer under another brand name. THREE send paths in email_router passed the raw Organization row to send_email_via_provider. Restland has no from_email of its own, so the sender fell through to the deployment-wide EMAIL_FROM_ADDRESS and a Restland family received mail From noreply@bookaboost.live - a company they have never heard of - which their employer mail gateway then put in Junk behind an arrived-from-outside warning. All three now pass sending_identity_for_org, which walks organization to platform to verified registry and carries reply-to and cc. public_identity deliberately returns from_email None rather than guess a brand; send_email_via_provider substituted the shared default one line later, defeating the resolver entirely - SendingIdentity now marks itself resolved and the sender REFUSES rather than borrowing a brand. Also: the template path and the two message records passed current_user instead of acting_advisor, so a template email sent under impersonation was signed with the platform owner name instead of the family own advisor.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
